"""Concept UI contract through real browser/HTTP, using explicit fake inference."""
import os
import pytest
from test_browser import ask
from test_browser_3d import scene_page, snapshot
from test_browser_v2 import building_server, upload_building, BuildingFixtureProvider
from test_browser_v3 import semantic_server, generate

pytestmark = pytest.mark.skipif(os.getenv('RUN_BROWSER_TESTS') != '1', reason='opt-in browser checks')


def settle(page):
    page.wait_for_timeout(500)


def test_concept_mode_cache_source_isolation_and_inspection_return(building_server, scene_page):
    from playwright.sync_api import expect
    page = scene_page
    page.goto(building_server)
    upload_building(page)
    page.locator('#generate-scene').click()
    page.wait_for_function('window.blueprintViewer?.data.derived === true')
    scene = page.evaluate('window.blueprintViewer.data')
    floors = scene['floors']
    page.locator('#floor-select').select_option(floors[1]['id'])
    page.locator('#show-assumptions').check()
    settle(page)
    inspection = snapshot(page)
    page.evaluate('window.savedSceneJSON=JSON.stringify(window.blueprintViewer.data);window.savedViewer=window.blueprintViewer')
    requests = []
    page.on('request', lambda req: requests.append(req.url) if '/api/' in req.url else None)
    page.locator('#show-concept').click()
    page.wait_for_function('window.blueprintViewer.getSnapshot().mode === "concept"')
    first = snapshot(page)
    assert first['floor_filter'] == floors[0]['id']
    assert first['cutaway']
    expect(page.locator('#scene-badge')).to_be_hidden()
    expect(page.locator('#layout-note')).to_be_hidden()
    expect(page.locator('#show-assumptions')).to_be_hidden()
    page.locator('#floor-select').select_option(floors[0]['id'])
    page.locator('#concept-cutaway').uncheck()
    assert not snapshot(page)['cutaway']
    page.locator('#concept-cutaway').check()
    canvas = page.locator('#model-canvas-container canvas')
    canvas.scroll_into_view_if_needed()
    box = canvas.bounding_box()
    before = snapshot(page)['camera_position']
    page.mouse.move(box['x']+box['width']*.45, box['y']+box['height']*.5)
    page.mouse.down()
    page.mouse.move(box['x']+box['width']*.65, box['y']+box['height']*.56, steps=8)
    page.mouse.up()
    settle(page)
    assert snapshot(page)['camera_position'] != before
    page.mouse.wheel(0, -180)
    settle(page)
    page.locator('#fit-model').click()
    settle(page)
    concept = snapshot(page)
    assert not requests, 'Deterministic scene interaction must make no API calls'
    ask(page, 'Where is Room 3?')  # answer references another floor
    settle(page)
    after = snapshot(page)
    assert after['floor_filter'] == concept['floor_filter']
    assert after['camera_position'] == pytest.approx(concept['camera_position'])
    assert after['concept_build_count'] == first['concept_build_count'] == 1
    assert page.evaluate('window.savedViewer===window.blueprintViewer && window.savedSceneJSON===JSON.stringify(window.blueprintViewer.data)')
    page.locator('.evidence-item').first.click()
    expect(page.locator('#evidence-overlay')).to_be_visible()
    expect(page.locator('#page-label')).to_have_text('Page 2 of 2')
    page.locator('#show-model').click()
    current = snapshot(page)
    assert current['mode'] == 'inspection'
    assert current['floor_filter'] == inspection['floor_filter']
    assert current['exploded'] == inspection['exploded']
    assert current['show_assumptions']
    # Camera is restored within floating-point tolerance (controls may settle).
    assert current['camera_position'] == pytest.approx(inspection['camera_position'], abs=1e-5)
    assert current['highlight_ids']
    assert any(e['opacity'] == .1 for e in current['elements'])
    page.locator('#show-concept').click()
    assert snapshot(page)['floor_filter'] == concept['floor_filter']
    ask(page, 'What is the actual ceiling height?')
    expect(page.locator('#result-status')).to_have_text('Missing information')
    assert snapshot(page)['highlight_ids'] == []
    assert snapshot(page)['concept_build_count'] == 1
    assert BuildingFixtureProvider.calls == 1
    page.set_viewport_size({'width':390, 'height':844})
    assert page.evaluate('document.documentElement.scrollWidth <= innerWidth')


def test_concept_semantic_geometry_and_replace_dispose(semantic_server, scene_page):
    page = scene_page
    generate(page, semantic_server)
    page.locator('#show-concept').click()
    first = page.evaluate('window.blueprintViewer.data')
    page.evaluate('window.retiredViewer=window.blueprintViewer')
    page.locator('#concept-cutaway').uncheck()
    page.locator('#concept-cutaway').check()
    page.locator('#show-model').click()
    chair = next(e for e in first['elements'] if e['semantic_type'] == 'chair')
    page.locator('#element-select').select_option(chair['id'])
    page.locator('#element-source').click()
    assert page.locator('#evidence-overlay').is_visible()
    generate(page, semantic_server)
    page.locator('#show-concept').click()
    assert snapshot(page)['concept_build_count'] == 1
    assert snapshot(page)['mesh_count'] > 0

